# ----------------------------
# a) Calculator using Functions
# ----------------------------
def calculator(a, b, op):
    if op == '+':
        return a + b
    elif op == '-':
        return a - b
    elif op == '*':
        return a * b
    elif op == '/':
        if b == 0:
            return "Division by zero not allowed"
        return a / b
    else:
        return "Invalid operator"


# ----------------------------
# b) Reverse of an Integer
# ----------------------------
def reverse_num(n):
    rev = 0
    while n > 0:
        rem = n % 10
        rev = rev * 10 + rem
        n = n // 10
    return rev


# ----------------------------
# c) Leap Year Checker
# ----------------------------
def is_leap(year):
    if year % 400 == 0:
        return True
    elif year % 100 == 0:
        return False
    elif year % 4 == 0:
        return True
    else:
        return False


# ----------------------------
# d) Month Number to Name
# ----------------------------
def month_name(num):
    if num == 1:
        return "January"
    elif num == 2:
        return "February"
    elif num == 3:
        return "March"
    elif num == 4:
        return "April"
    elif num == 5:
        return "May"
    elif num == 6:
        return "June"
    elif num == 7:
        return "July"
    elif num == 8:
        return "August"
    elif num == 9:
        return "September"
    elif num == 10:
        return "October"
    elif num == 11:
        return "November"
    elif num == 12:
        return "December"
    else:
        return "Invalid month number"


# ----------------------------
# e) Check if numbers are sorted
# ----------------------------
def is_sorted(a, b, c):
    if a <= b and b <= c:
        print("Numbers are sorted:", a, b, c)
        return True
    else:
        # Manual sorting without sorted()
        if a > b:
            temp = a
            a = b
            b = temp
        if b > c:
            temp = b
            b = c
            c = temp
        if a > b:
            temp = a
            a = b
            b = temp
        print("Numbers are not sorted. Sorted order is:", a, b, c)
        return False


# ----------------------------
# Sample Runs
# ----------------------------
if __name__ == "__main__":
    # a)
    print("Calculator Example:", calculator(10, 5, '+'))

    # b)
    print("Reverse of 1234:", reverse_num(1234))

    # c)
    print("Is 2024 a leap year?", is_leap(2024))

    # d)
    print("Month for 7:", month_name(7))

    # e)
    print("Sorted check (3, 5, 8):", is_sorted(3, 5, 8))
    print("Sorted check (8, 2, 5):", is_sorted(8, 2, 5))
```

